1632:   // ── Resolver de links cortos de Google Maps ────────────────────────────────
1633:   // Sigue los redirects manualmente (nunca automáticos), valida cada salto
1634:   // contra la allowlist de Google, bloquea credenciales/puertos y aplica timeout.
1635:   app.get("/api/maps/resolve", requireAuth, mapsLimiter, async (req: any, res) => {
1636:     const readUrl = (value: unknown): URL | null => {
1637:       try {
1638:         const parsed = new URL(String(value));
1639:         if (parsed.protocol !== "https:") return null;
1640:         if (parsed.username || parsed.password) return null;
1641:         if (parsed.port && parsed.port !== "443") return null;
1642:         const allowedHosts = new Set([
1643:           "maps.app.goo.gl",
1644:           "goo.gl",
1645:           "g.co",
1646:           "www.google.com",
1647:           "google.com",
1648:           "maps.google.com",
1649:         ]);
1650:         if (!allowedHosts.has(parsed.hostname.toLowerCase())) return null;
1651:         return parsed;
1652:       } catch {
1653:         return null;
1654:       }
1655:     };
1656: 
1657:     try {
1658:       const requested = readUrl(req.query.url);
1659:       if (!requested) {
1660:         return res.status(400).json({ error: "URL de Google Maps inválida" });
1661:       }
1662: 
1663:       let current = requested;
1664:       for (let hop = 0; hop < 5; hop++) {
1665:         const response = await fetch(current, {
1666:           method: "GET",
1667:           redirect: "manual",
1668:           signal: AbortSignal.timeout(5_000),
1669:           headers: {
1670:             "User-Agent":
1671:               "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Safari/537.36",
1672:           },
1673:         });
1674: 
1675:         if (response.status >= 300 && response.status < 400) {
1676:           const location = response.headers.get("location");
1677:           if (!location) break;
1678:           const next = readUrl(new URL(location, current).toString());
1679:           if (!next) {
1680:             return res.status(400).json({ error: "Redirección fuera de Google Maps bloqueada" });
1681:           }
1682:           current = next;
1683:           continue;
1684:         }
1685:         break;
1686:       }
1687: 
1688:       return res.json({ url: current.toString() });
1689:     } catch {
1690:       return res.status(502).json({ error: "No se pudo resolver el link de Google Maps" });
1691:     }
1692:   });
