472: export function encryptSensitive(plaintext: unknown): string | null {
473:   const value = String(plaintext ?? "").trim();
474:   if (!value) return null;
475:   const iv = crypto.randomBytes(12);
476:   const cipher = crypto.createCipheriv("aes-256-gcm", paymentKey(), iv);
477:   const encrypted = Buffer.concat([cipher.update(value, "utf8"), cipher.final()]);
478:   const tag = cipher.getAuthTag();
479:   return `enc:v1:${iv.toString("base64url")}:${tag.toString("base64url")}:${encrypted.toString("base64url")}`;
480: }
