482: export function decryptSensitive(value: unknown): string | null {
483:   const raw = String(value ?? "");
484:   if (!raw) return null;
485:   if (!raw.startsWith("enc:v1:")) return raw; // dato legacy en texto plano
486:   try {
487:     const [, , ivB64, tagB64, dataB64] = raw.split(":");
488:     const decipher = crypto.createDecipheriv("aes-256-gcm", paymentKey(), Buffer.from(ivB64, "base64url"));
489:     decipher.setAuthTag(Buffer.from(tagB64, "base64url"));
490:     return Buffer.concat([decipher.update(Buffer.from(dataB64, "base64url")), decipher.final()]).toString("utf8");
491:   } catch {
492:     return null;
493:   }
494: }
