75:     const status = err.status || err.statusCode || 500;
76:     if (status >= 500) logServerError(err, (req as any).requestId);
77: 
78:     let message = err.message || "Internal Server Error";
79:     if (err?.code === "LIMIT_FILE_SIZE") {
80:       res.status(413);
81:       return res.json({ message: "El archivo excede el tamaño máximo permitido" });
82:     }
83:     if (status >= 500 && process.env.NODE_ENV === "production") {
