35: export function sniffMime(buffer: Buffer): string | null {
36:   if (!buffer || buffer.length < 4) return null;
37: 
38:   if (startsWith(buffer, [0xff, 0xd8, 0xff])) return "image/jpeg";
39:   if (startsWith(buffer, [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a])) return "image/png";
40:   if (ascii(buffer, 0, 4) === "GIF8") return "image/gif";
41:   if (ascii(buffer, 0, 4) === "RIFF" && ascii(buffer, 8, 12) === "WEBP") return "image/webp";
42:   if (ascii(buffer, 4, 8) === "ftyp") return "video/mp4";
43:   if (startsWith(buffer, [0x1a, 0x45, 0xdf, 0xa3])) return "video/webm";
44:   if (ascii(buffer, 0, 4) === "glTF") return "model/gltf-binary";
45: 
46:   const head = buffer.slice(0, 512).toString("utf8").trim();
47:   if (head.startsWith("{") && /"asset"\s*:/.test(head) && /"version"\s*:/.test(head)) {
48:     return "model/gltf+json";
49:   }
50: 
51:   return null;
52: }
