55:   "image/jpeg": "jpg",
56:   "image/png": "png",
57:   "image/gif": "gif",
58:   "image/webp": "webp",
59:   "video/mp4": "mp4",
60:   "video/webm": "webm",
61:   "model/gltf-binary": "glb",
62:   "model/gltf+json": "gltf",
63: };
