66:   const { buffer } = input;
67:   if (!buffer || buffer.length === 0) return { ok: false, reason: "El archivo está vacío" };
68: 
69:   const realMime = sniffMime(buffer);
70:   if (!realMime) {
71:     return { ok: false, reason: "El contenido del archivo no corresponde a un formato permitido" };
72:   }
73: 
74:   const extension = String(input.originalname || "").split(".").pop()?.toLowerCase() || "";
75:   const expectedExtension = EXTENSIONS[realMime];
76: 
77:   if (extension && extension !== expectedExtension && !(realMime === "image/jpeg" && extension === "jpeg")) {
78:     return { ok: false, reason: "La extensión no coincide con el contenido real del archivo" };
79:   }
80: 
81:   // application/octet-stream solo se tolera para modelos 3D reales.
82:   if (input.mimetype === "application/octet-stream" && !realMime.startsWith("model/")) {
83:     return { ok: false, reason: "Tipo MIME genérico no permitido para este archivo" };
84:   }
85: 
86:   if (input.mimetype && input.mimetype !== "application/octet-stream" && input.mimetype !== realMime) {
87:     return { ok: false, reason: "El tipo MIME declarado no coincide con el contenido real" };
88:   }
89: 
90:   const kind: UploadKind = realMime.startsWith("image/")
91:     ? "image"
92:     : realMime.startsWith("video/")
93:       ? "video"
94:       : "model";
95: 
96:   const maxBytes =
97:     kind === "image"
98:       ? input.maxImageBytes ?? DEFAULT_MAX_IMAGE
99:       : kind === "video"
100:         ? input.maxVideoBytes ?? DEFAULT_MAX_VIDEO
101:         : input.maxModelBytes ?? DEFAULT_MAX_MODEL;
102: 
103:   if (buffer.length > maxBytes) {
104:     return { ok: false, reason: "El archivo excede el tamaño máximo permitido para su tipo" };
105:   }
106: 
107:   return { ok: true, kind, mime: realMime, extension: expectedExtension };
