res.json({
  profile: {
    ...publicProfile,
    contactVisibility: visibility,
    contact: hasContact ? contact : null,
    postsCount: Number(postsCount?.c || 0),
    followers: Number(followers?.c || 0),
    following: Number(following?.c || 0),
    ...state,
  },
});

