async getUserProfile(username: string): Promise<{
  username: string;
  name: string | null;
  role: string | null;
  avatarUrl: string | null;
  bannerUrl: string | null;
  bio: string | null;
  roles: Array<{ role: string; businessName: string | null; createdAt: Date | null }>;
  averageRating: number;
  reviewCount: number;
} | null> {
  const user = await this.getUserByUsername(username);
  if (!user) return null;
  const [roleRecords, avgRating, revs] = await Promise.all([
    this.getUserRoles(user.id),
    this.getAverageRating(username),
    this.getReviewsByUsername(username),
  ]);
  return {
    username: user.username,
    name: user.name,
    role: user.role,
    avatarUrl: user.avatarUrl,
    bannerUrl: user.bannerUrl,
    bio: user.bio,
    // Minimización: nunca exponer teléfono, placa, dirección del negocio ni
    // datos de contacto desde este endpoint público.
    roles: roleRecords.map((record) => ({
      role: String(record.role),
      businessName: record.businessName ?? null,
      createdAt: record.createdAt ?? null,
    })),
    averageRating: avgRating,
    reviewCount: revs.length,
  };
}

