                        const active = form.contactVisibility === option.value;
                        return (
                          <label
                            key={option.value}
                            className={`flex cursor-pointer items-start gap-2 rounded-xl border p-3 text-sm transition ${
                              active
                                ? "border-primary/60 bg-primary/10"
